import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易附录纂注卷十四","description":"易附录纂注 - 易附录纂注卷十四","frontmatter":{"title":"易附录纂注卷十四","description":"易附录纂注 - 易附录纂注卷十四"},"headers":[],"relativePath":"zh/classics/yifulu-zuanzhu/015.md","filePath":"zh/classics/yifulu-zuanzhu/015.md"}'),r={name:"zh/classics/yifulu-zuanzhu/015.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附录纂注卷十四",tabindex:"-1"},[n("易附录纂注卷十四 "),e("a",{class:"header-anchor",href:"#易附录纂注卷十四","aria-label":"Permalink to “易附录纂注卷十四”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"元胡一桂撰",-1),e("p",null,"择地洁处为蓍室，南户，置床于室中央。 床大约长五尺，广三尺，毋太近壁。 蓍五十茎，韬以𫄸帛，贮以皂囊，纳之椟中，置于床北。 椟以竹筒，或坚木，或布漆为之，圆径三寸，如蓍之长，半为底，半为盖，下别为台，函之使不偃仆。 附录。 蒿固非蓍，然亦犹是其类。若以木棋行算金钱当之，则其去蓍益远矣。答曾三异。 设木格于椟南，居床二分之北。 格以横木板为之，高一尺，长竟床。当中为两大刻，相距一尺。大刻之西为三小刻，相距各五寸许。下施横足，侧立案上。 置香炉一于格南，香合一于炉南。日炷香致敬。将筮，则洒扫拂拭，涤砚一、注水及笔一、墨一、黄漆板一于炉东，东上。筮者齐洁衣冠，北面盥手焚香致敬。 筮者北面，见仪礼。若使人筮，则主人焚香毕，少退，北面立。筮者进，立于床前，少西，南向受命。主人直述所占之事，筮者许诺。主人右还，西向立，筮者右还北向立。 两手奉椟盖置于格南炉北，出蓍于椟，去囊解韬，置于椟东，合五十策，两手执之，熏于炉上， 此后所用蓍策之数，其说并见启蒙。 命之曰：「假尔泰筮有常，假尔泰筮有常，某官姓名，今以某事云云，未知可否。爰质所疑，于神于灵。吉凶得失，悔吝忧虞，惟尔有神，尚明告之。」乃以右手取其一策反于椟中，而以左右手中分四十九策置格之左右两大刻， 此第一营所谓「分而为二以象两」者也。 次以左手取左大刻之策执之，而以右手取右大刻之一策挂于左手之小指间， 此第二营所谓「挂一以象三」者也。 次以右手四揲左手之策， 此第三营之半，所谓「揲之以四以象四时」者也。 次归其所余之策，或一、或二、或三、或四，而扐之左手无名指间， 此第四营之半，所谓「归奇于扐以象闰」者也。 次以右手反过揲之策于左大刻，遂取右大刻之策执之，而以左手四揲之。 此第三营之半。 次归其所余之策如前，而扐之左手中指之间。 此第四营之半，所谓「再扐以象再闰」者也。一变所余之策，左一则右必三，左二则右亦二，左三则右必一，左四则右亦四。通挂一之策，不五则九，五以一其四而为奇，九以两其四而为偶，奇者三而偶者一也。 次以右手反过揲之策于右大刻，而合左手一挂二扐之策，置于格上第一小刻， 以东为上，后放此。 是为一变。再以两手取左右大刻之蓍合之， 或四十四策，或四十策。 复四营如第一变之仪，而置其挂扐之策于格上第二小刻，是为二变。 二变所余之策，左一则右必二，左二则右必一，左三则右必四，左四则右必三。通挂一之策，不四则八，四以一其四而为奇，八以两其四而为偶，奇偶各得四之二焉。 又再取左右大刻之蓍合之， 或四十策，或三十六策，或三十二策。 履四营如第二变之仪，而置其挂扐之策于格上，第三小刻，是为三变。 三变余策，与二变同。 三变既毕，乃视其三变所得挂扐过揲之策，而画其爻于版。 挂扐之数，五、四为奇，九、八为偶。挂扐三奇合十三策，则过揲三十六策，而为老阳，其画为口，所谓「重」也。挂扐两奇一偶合十七策，则过揲三十二策而为少阴，其画为一，所谓「拆」也。挂扐两偶一奇合二十一策，则过揲二十八策而为少阳，其画为一，所谓「单」也。挂扐三偶合二十五策，则过揲二十四策而为老阴，其画为乂，所谓「交」也。 附录：交者，拆之聚，故为老阴；重者，单之积，故为老阳。 如是每三变而成爻。 第一、第四、第七、第十、第十三、第十六，凡六变并同。但第三变以下不命，而但用四十九蓍耳。第二、第五、第八、第十一、第十四、第十七，凡六变亦同。第三、第六、第九、第十二、第十五、第十八，凡六变亦同。 凡十有八变而成卦，乃考其卦之变，而占其事之吉凶。 卦变别有图，说见启蒙。 礼毕，韬蓍，袭之以囊，入椟加盖，敛笔研墨版，再焚香致敬而退。 如使人筮，则主人焚香揖筮者而退。 易附录纂注卷十四",-1)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
